import 'package:flutter/material.dart';
import 'profile_service.dart';

class ProfilePage extends StatefulWidget{const ProfilePage({super.key});@override State<ProfilePage> createState()=>_ProfilePageState();}
class _ProfilePageState extends State<ProfilePage>{final _service=ProfileService();final _name=TextEditingController();final _education=TextEditingController();final _role=TextEditingController();bool _loaded=false;bool _busy=false;String? _error;
Future<void> _load()async{try{final p=await _service.getProfile();if(p!=null){_name.text='${p['name']??''}';_education.text='${p['education']??''}';_role.text='${p['target_role']??''}';}}catch(e){_error=e.toString();}finally{if(mounted)setState(()=>_loaded=true);}}
Future<void> _save()async{try{setState(()=>_busy=true);await _service.saveProfile(name:_name.text,education:_education.text,targetRole:_role.text);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile saved.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>_busy=false);}}
@override void initState(){super.initState();_load();}@override void dispose(){_name.dispose();_education.dispose();_role.dispose();super.dispose();}
@override Widget build(BuildContext context){if(!_loaded)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(20),children:[Text('Your Profile',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:16),if(_error!=null)Text(_error!,style:const TextStyle(color:Colors.red)),TextField(controller:_name,decoration:const InputDecoration(labelText:'Full name')),const SizedBox(height:12),TextField(controller:_education,decoration:const InputDecoration(labelText:'Education')),const SizedBox(height:12),TextField(controller:_role,decoration:const InputDecoration(labelText:'Target job role')),const SizedBox(height:20),FilledButton(onPressed:_busy?null:_save,child:Text(_busy?'Saving...':'Save profile'))]);}}
